INSERT INTO hecho (id_tipo_hecho, id_ubicacion, fecha_hecho) SELECT (SELECT id_tipo_hecho FROM tipo_hecho WHERE UPPER(TRIM(nombre)) = UPPER('hecho_delictivo') ROWS 1), p.id_origen, '2023-10-02' FROM persona p WHERE p.nombres = 'AGR_2023_396398' AND p.apellidos = 'AGRAVIADOS' AND NOT EXISTS (SELECT 1 FROM hecho h JOIN involucrado_hecho ih ON ih.id_hecho = h.id_hecho WHERE ih.id_involucrado = p.id_persona   AND h.fecha_hecho = '2023-10-02');
INSERT INTO involucrado_hecho (id_hecho, id_involucrado, id_tipo_involucramiento) SELECT (SELECT h.id_hecho FROM hecho h  WHERE h.id_ubicacion = p.id_origen    AND h.fecha_hecho = '2023-10-02'  ORDER BY h.id_hecho DESC ROWS 1), p.id_persona, COALESCE((SELECT id_involucramiento FROM involucramiento WHERE UPPER(TRIM(nombre)) = UPPER('Agraviado') ROWS 1),          (SELECT id_involucramiento FROM involucramiento WHERE UPPER(TRIM(nombre)) = UPPER('Victimario') ROWS 1)) FROM persona p WHERE p.nombres = 'AGR_2023_396398' AND p.apellidos = 'AGRAVIADOS' AND NOT EXISTS (SELECT 1 FROM involucrado_hecho ih WHERE ih.id_involucrado = p.id_persona   AND ih.id_hecho = (SELECT h.id_hecho FROM hecho h  WHERE h.id_ubicacion = p.id_origen    AND h.fecha_hecho = '2023-10-02'  ORDER BY h.id_hecho DESC ROWS 1));
INSERT INTO hecho_delictivo (id_hecho, id_delito) SELECT (SELECT h.id_hecho FROM hecho h  WHERE h.id_ubicacion = p.id_origen    AND h.fecha_hecho = '2023-10-02'  ORDER BY h.id_hecho DESC ROWS 1), dc.id_delito_cometido FROM persona p JOIN delito d ON d.codigo = 'AGR-DEL-053' JOIN clasificacion_delito c ON UPPER(TRIM(c.nombre)) = UPPER('Lesiones leves') JOIN delito_cometido dc ON dc.id_tipo_delito = d.id_delito AND dc.id_clasificacion_delito = c.id_clasificacion_delito WHERE p.nombres = 'AGR_2023_396398' AND p.apellidos = 'AGRAVIADOS' AND NOT EXISTS (SELECT 1 FROM hecho_delictivo hd WHERE hd.id_hecho = (SELECT h.id_hecho FROM hecho h  WHERE h.id_ubicacion = p.id_origen    AND h.fecha_hecho = '2023-10-02'  ORDER BY h.id_hecho DESC ROWS 1)   AND hd.id_delito = dc.id_delito_cometido);
